/**
 * Standard 14 PDF Fonts
 *
 * These are the 14 fonts that every PDF reader must support.
 * They don't require embedding - the reader provides them.
 *
 * Width tables are stored by glyph name (like pdf.js) which works
 * with any encoding. Use getWidthByGlyphName() for lookup.
 *
 * Widths are in glyph units (1000 units = 1 em).
 *
 * Data extracted from pdf.js metrics.js (Mozilla, Apache 2.0 License)
 */

import type { FontEncoding } from "#src/fonts/encodings/encoding";
import { SymbolEncoding } from "#src/fonts/encodings/symbol";
import { WinAnsiEncoding } from "#src/fonts/encodings/win-ansi";
import { ZapfDingbatsEncoding } from "#src/fonts/encodings/zapf-dingbats";

/**
 * Standard 14 font names.
 */
export const STANDARD_14_FONTS = [
  "Courier",
  "Courier-Bold",
  "Courier-Oblique",
  "Courier-BoldOblique",
  "Helvetica",
  "Helvetica-Bold",
  "Helvetica-Oblique",
  "Helvetica-BoldOblique",
  "Times-Roman",
  "Times-Bold",
  "Times-Italic",
  "Times-BoldItalic",
  "Symbol",
  "ZapfDingbats",
] as const;

export type Standard14FontName = (typeof STANDARD_14_FONTS)[number];

/**
 * Standard 14 fonts enum for convenient access.
 *
 * @example
 * ```typescript
 * page.drawText("Hello", { font: StandardFonts.Helvetica });
 * page.drawText("Bold", { font: StandardFonts.HelveticaBold });
 * ```
 */
export const StandardFonts = {
  Helvetica: "Helvetica",
  HelveticaBold: "Helvetica-Bold",
  HelveticaOblique: "Helvetica-Oblique",
  HelveticaBoldOblique: "Helvetica-BoldOblique",

  TimesRoman: "Times-Roman",
  TimesBold: "Times-Bold",
  TimesItalic: "Times-Italic",
  TimesBoldItalic: "Times-BoldItalic",

  Courier: "Courier",
  CourierBold: "Courier-Bold",
  CourierOblique: "Courier-Oblique",
  CourierBoldOblique: "Courier-BoldOblique",

  Symbol: "Symbol",
  ZapfDingbats: "ZapfDingbats",
} as const satisfies Record<string, Standard14FontName>;

/**
 * Basic metrics for a font.
 */
export interface FontBasicMetrics {
  ascent: number;
  descent: number;
  capHeight: number;
  xHeight: number;
}

/**
 * Check if a font name is a Standard 14 font.
 * Handles subset prefixes like "ABCDEF+Helvetica".
 */
export function isStandard14Font(name: string): boolean {
  const baseName = getBaseFontName(name);

  return (STANDARD_14_FONTS as readonly string[]).includes(baseName);
}

/**
 * Get the base name without subset prefix.
 */
export function getBaseFontName(name: string): string {
  return name.includes("+") ? name.split("+")[1] : name;
}

/**
 * Get the font encoding for a Standard 14 font.
 *
 * - Symbol → SymbolEncoding
 * - ZapfDingbats → ZapfDingbatsEncoding
 * - All others (Helvetica, Times, Courier) → WinAnsiEncoding
 */
export function getEncodingForStandard14(name: string): FontEncoding {
  const baseName = getBaseFontName(name);

  if (baseName === "Symbol") {
    return SymbolEncoding.instance;
  }

  if (baseName === "ZapfDingbats") {
    return ZapfDingbatsEncoding.instance;
  }

  return WinAnsiEncoding.instance;
}

/**
 * Check if a Standard 14 font uses WinAnsiEncoding.
 * Returns false for Symbol and ZapfDingbats (they use built-in encodings).
 */
export function isWinAnsiStandard14(name: string): boolean {
  const baseName = getBaseFontName(name);

  return baseName !== "Symbol" && baseName !== "ZapfDingbats";
}

/**
 * Get basic metrics (ascent, descent, etc.) for a Standard 14 font.
 */
export function getStandard14BasicMetrics(name: string): FontBasicMetrics | undefined {
  const baseName = getBaseFontName(name);

  return FONT_BASIC_METRICS[baseName];
}

/**
 * Get width for a glyph in a Standard 14 font.
 * Returns undefined if font or glyph not found.
 */
export function getStandard14GlyphWidth(fontName: string, glyphName: string): number | undefined {
  const baseName = getBaseFontName(fontName);
  const metrics = FONT_GLYPH_WIDTHS[baseName];

  if (!metrics) {
    return undefined;
  }

  // Courier family is monospace - all glyphs are 600
  if (typeof metrics === "number") {
    return metrics;
  }

  return metrics[glyphName];
}

/**
 * Get the default width for missing glyphs in a Standard 14 font.
 */
export function getStandard14DefaultWidth(fontName: string): number {
  const baseName = getBaseFontName(fontName);
  if (baseName.startsWith("Courier")) {
    return 600;
  }

  if (baseName.startsWith("Helvetica")) {
    return 278;
  }

  if (baseName.startsWith("Times")) {
    return 250;
  }

  if (baseName === "Symbol") {
    return 250;
  }

  if (baseName === "ZapfDingbats") {
    return 278;
  }

  return 250;
}

